import java.util.*;
public class Main {
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};

    static int c[][] = {{-1,0},{1,0},{0,-1},{0,1}};
    static int S, T, tot = 1, n, tt, inf;
    static int[] b = new int[1000], d = new int[1000000];
    static int[] q = new int[1000000];
    static int[][] a = new int[1000000][3]; // [][0]: y, [][1]: capacity, [][2]: next edge index
    static int[][] dep = new int[20][20], dis = new int[20][20], p = new int[20][20], s = new int[20][20];
    static char[][] ma = new char[20][20], mb = new char[20][20];

    static void add(int x, int y, int c) {
        a[++tot][0] = y;
        a[tot][1] = c;
        a[tot][2] = b[x];
        b[x] = tot;
        a[++tot][0] = x;
        a[tot][1] = 0;
        a[tot][2] = b[y];
        b[y] = tot;
    }

    static void bfs(int x0, int y0, boolean flag) {
        int l=0, r=0;
        q[r++] = x0*1000 + y0;
        for (int[] row : dis) Arrays.fill(row, Integer.MAX_VALUE);
        int id = p[x0][y0];
        dis[x0][y0] = 0;
        while (l < r) {
            int val = q[l++];
            int x = val / 1000, y=y=val % 1000;
            if (flag && s[x][y] != 0 && dis[x][y] <= tt && dis[x][y] <= dep[x][y])
                add(id, s[x][y], Integer.MAX_VALUE);
            if (dis[x][y] > tt || dis[x][y] >= dep[x][y]) continue;
            if (id == 3 && s[x][y] == 9)
                System.out.println(dis[x][y]);
            for (int i=0; i<4; i++){
                int nx=x+dx[i], ny=y+dy[i];
                if (nx > 0 && nx <= n && ny > 0 && ny <= n && Character.isDigit(ma[nx][ny]) && dis[nx][ny]==Integer.MAX_VALUE){
                    dis[nx][ny] = dis[x][y] + 1;
                    q[r++] = nx*1000+ny;
                }
            }
        }
    }

    static boolean build() {
        Arrays.fill(d,0);
        int l=0, r=0;
        q[r++] = S;
        d[S]=1;
        while (l < r) {
            int x = q[l++];
            for (int i = b[x]; i != 0; i=a[i][2]) {
                int y=a[i][0];
                if (d[y] != 0 || a[i][1] ==0) continue;
                d[y]=d[x]+1;
                q[r++]=y;
                if (y==T) return true;
            }
        }
        return false;
    }

    static int dinic(int x,int flow) {
        if (x==T) return flow;
        int k=flow;
        for (int i = b[x]; i != 0; i=a[i][2]) {
            int y=a[i][0];
            if (d[y]!=d[x]+1 || a[i][1]==0) continue;
            int t=dinic(y, Math.min(k,a[i][1]));
            k -= t;
            a[i][1] -= t;
            a[i^1][1] += t;
            if (k==0) return flow;
        }
        if (k==flow) d[x]=-1;
        return flow - k;
    }

    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        n = sc.nextInt();
        tt = sc.nextInt();

        for (int i=1; i<=n; i++) {
            String line = sc.next();
            ma[i]=new char[n+1];
            for (int j=1; j<=n; j++) {
                ma[i][j] = line.charAt(j-1);
            }
        }
        for (int i=1; i<=n; i++) {
            String line = sc.next();
            mb[i]=new char[n+1];
            for (int j=1; j<=n; j++) {
                mb[i][j] = line.charAt(j-1);
            }
        }

        for (int i=0; i<20; i++) Arrays.fill(dep[i], Integer.MAX_VALUE);
        for (int i=1; i<=n; i++)
            for (int j=1; j<=n; j++)
                if (ma[i][j]=='Z') {
                    bfs(i,j,false);
                }

        for (int i=0; i<20; i++)
            for (int j=0; j<20; j++)
                dep[i][j] = dis[i][j];

        int t=1;
        S=0; T=1;

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (Character.isDigit(ma[i][j]) && ma[i][j]>'0' && ma[i][j]<='9') {
                    p[i][j]=++t;
                    add(S, p[i][j], ma[i][j]-'0');
                }
                if (Character.isDigit(mb[i][j]) && mb[i][j]>'0' && mb[i][j]<='9') {
                    s[i][j]=++t;
                    add(s[i][j], T, mb[i][j]-'0');
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (p[i][j] !=0)
                    bfs(i,j,true);
            }
        }

        int ans=0;
        while (build()) {
            int flow=dinic(S,Integer.MAX_VALUE);
            ans += flow;
        }

        System.out.println(ans);
    }
}
